arguments.command:
cd /workspace && ls -la data data/main && python3 - <<'PY'
import json,sys
try:
    import pyarrow.parquet as pq
except ImportError:
    print("no pyarrow"); sys.exit()
for f in ["data/train.parquet","data/test.parquet"]:
    t=pq.read_table(f)
    print(f, "rows=",t.num_rows, "cols=",t.column_names)
    r=t.slice(0,2).to_pylist()
    for row in r:
        print("   ", {k:(str(v)[:150]) for k,v in row.items()})
